INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63074638', 63074638, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR BIOMEDIS DAN GENOMIKA KESEHATAN', 'Pelaksanaan Pembangunan Gedung Gene Bank Indonesia', 'Pekerjaan Konstruksi', 'Pembayaran untuk Kontrak Tahun Jamak', 'Jawa Barat, Bogor (Kota)', 416196963000, 'August 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', 'Berdasarkan Surat Direktur Jenderal Pelayanan Kesehatan Nomor TK.02.03/D/8560/2023 tanggal 3 Agustus 2023, perihal Lokasi Pembangunan Gene bank, yang ditujukan ke Direktur Utama RS Jiwa dr. H. Marzoeki Mahdidan Kepala BBLK Jakarta, telah disetujui pembangunan Gedung GeneBank berlokasi di RS Jiwa dr. H. Marzoeki Mahdi, Kota Bogor. Lahan tersebut adalah milik Kementerian Kesehatan yang tercatat di RS dr. H. Marzoeki Mahdi dan selanjutnya akan dilakukan proses pencatatan aset pada satker Balai Besar Biomedis dan Genomika Kesehatan, sedangkan proses clearance akan dilakukan oleh Sekretariat Direktorat Jenderal Pelayanan Kesehatan setelah gedung terbangun. Pembangunan Gedung GeneBank direncanakan dengan skema penganggaran Kontrak Tahun Jamak (KTJ) TA 2025 – 2026, dibangun di atas lahan +2.5 hektar, ketinggian bangunan 7 (lantai) lantai dengan rencana kebutuhan fungsi ruang kegiatan sekuensing kapasitas besar, biorepository dan pengelolaan data spesimen dan genomik hasil analisis primer, sekunder dan tersier. Luasan bangunan yang diperlukan adalah +30.000 m2.', 'Secara umum, pembangunan fisik bangunan ini diarahkan untuk menjadi fasilitas skala nasional dan berstandar internasional. Berikut di bawah ini informasi lahan, perkiraan luas total gedung, jumlah lantai, dan Program Ruang beserta persyaratan teknis: Lokasi : RS dr. H. Marzoeki Mahdi Jl. DR. Sumeru No.114, RT.02/RW.01, Menteng, Kec. Bogor Bar., Kota Bogor, Jawa Barat Luas Lahan : + 2.5 hektar Luas Total Bangunan : + 30.000 m2 Jumlah Lantai : 7 lantai', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 582515);
